static void induce_s_8_64(SaisBytes text, SaisInt64s sa, SaisInt64s freq,
                          SaisInt64s bucket) {
    /* Initialize positions for right side of character buckets. */
    bucket_max_8_64(text, freq, bucket);
    bucket.len = 256; /* eliminate bounds check for bucket[cB] below */

    Byte c_b = 0;
    int64_t b = bucket.p[c_b];

    for (Int i = sa.len - 1; i >= 0; i--) {
        Int j = (Int)sa.p[i];
        if (j >= 0) {
            /* Skip non-flagged entry.
             * (This loop can't see an empty entry; 0 means the real zero
             * index.) */
            continue;
        }

        /* Negative j is a work queue entry; rewrite to positive j for final
         * suffix array. */
        j = -j;
        sa.p[i] = (int64_t)j;

        /* Index j was on work queue (encoded as -j but now decoded),
         * meaning k := j-1 is L-type,
         * so we can now place k correctly into sa.
         * If k-1 is S-type, queue -k for processing later in this loop.
         * If k-1 is L-type (text[k-1] > text[k]), queue k to save for the
         * caller. If k is zero, k-1 doesn't exist, so we only need to leave
         * it for the caller. */
        Int k = j - 1;
        Byte c1 = text.p[k];
        if (k > 0) {
            Byte c0 = text.p[k - 1];
            if (c0 <= c1)
                k = -k;
        }

        if (c_b != c1) {
            bucket.p[c_b] = b;
            c_b = c1;
            b = bucket.p[c_b];
        }
        b--;
        sa.p[b] = (int64_t)k;
    }
}

static void induce_s_32(SaisInt32s text, SaisInt32s sa, SaisInt32s freq,
                        SaisInt32s bucket) {
    /* Initialize positions for right side of character buckets. */
    bucket_max_32(text, freq, bucket);

    int32_t c_b = 0;
    int32_t b = bucket.p[c_b];

    for (Int i = sa.len - 1; i >= 0; i--) {
        Int j = (Int)sa.p[i];
        if (j >= 0) {
            /* Skip non-flagged entry.
             * (This loop can't see an empty entry; 0 means the real zero
             * index.) */
            continue;
        }

        /* Negative j is a work queue entry; rewrite to positive j for final
         * suffix array. */
        j = -j;
        sa.p[i] = (int32_t)j;

        /* Index j was on work queue (encoded as -j but now decoded),
         * meaning k := j-1 is L-type,
         * so we can now place k correctly into sa.
         * If k-1 is S-type, queue -k for processing later in this loop.
         * If k-1 is L-type (text[k-1] > text[k]), queue k to save for the
         * caller. If k is zero, k-1 doesn't exist, so we only need to leave
         * it for the caller. */
        Int k = j - 1;
        int32_t c1 = text.p[k];
        if (k > 0) {
            int32_t c0 = text.p[k - 1];
            if (c0 <= c1)
                k = -k;
        }

        if (c_b != c1) {
            bucket.p[c_b] = b;
            c_b = c1;
            b = bucket.p[c_b];
        }
        b--;
        sa.p[b] = (int32_t)k;
    }
}

